for i,(title,note) in enumerate([('M0 / direct passage (outlined ghost removed)','Declined: removing O03 keeps through-support but lets the bridge-facing reserve watch toward Fountain with little displacement.'),('M1 / shallow return selected','O03 forces a short southward move; two receiving exits remain after the turn. It adds clearing and delays follower trades.'),('U0 / open south civic edge','Declined: the whole span becomes a middle-crossing observation position; that weakens the cost of information.'),('U1 / bounded W02 selected','2.4 m south screen, one 3 m aperture. Stand on the span and turn away from its ends to gain a reciprocal middle view.')]):
 x=45+(i%2)*750;y=120+(i//2)*455
 body+=f'<text x="{x}" y="{y}" font-size="19" font-weight="700" fill="#294b55">{title}</text>'
 bounds=[74,47,100,67] if i<2 else [53,85,77,99]
 if i==2:
  originalWindows=v.d['windows'];originalEdges=v.d['boundaries']
  v.d['windows']=[w for w in originalWindows if w['id']!='W02']
  v.d['boundaries']=[dict(r,height=1.1) if r['z']==8 and 54<=sum(p[0] for p in [r['a'],r['b']])/2<=76 and 86.5<=sum(p[1] for p in [r['a'],r['b']])/2<=92.1 else r for r in originalEdges]
  body+=v.plan(8,bounds,(x,y+20,700,305),[],False)
  v.d['windows']=originalWindows;v.d['boundaries']=originalEdges
 else:body+=v.plan(4 if i<2 else 8,bounds,(x,y+20,700,305),[],False)
 if i==0:
  bx,by,bw,bh=x,y+20,700,305;s=min(bw/(bounds[2]-bounds[0]),bh/(bounds[3]-bounds[1]));xy2=lambda p:(bx+(p[0]-bounds[0])*s,by+(bounds[3]-p[1])*s)
  body+=f'<polygon points="{v.points(next(o["p"] for o in d["obstacles"] if o["id"]=="O03"),xy2)}" fill="#c6d8bd"/>'
 if i==2:body+=v.wrap('Counterfactual: replace full south screen with a 1.1 m open parapet.',x+12,y+297,86,12)
 body+=v.wrap(note,x,y+360,87,14)
body+=v.wrap('W03 is a separate School-balcony information position toward Fountain, not a substitute for W02 or an all-B overlook. Its full wall is 2.4 m with sill 1.1 / head 2.1. It requires leaving the CT-facing room and has a reciprocal ground challenge. No new movement edge is added by either aperture.',48,1060,176,14)
(out/'variant-comparison.svg').write_text(v.base(1540,1150,'GALINI / L03 / bounded arrival and information comparisons','Compatible selections only / comparison views are author predictions, not reviewer acceptance',body))
print('Wrote encounters, physical-walk waypoints, all vertical/shared sections, roofs and variants.')
